/**
 * Converts a THREE.BufferGeometry to OBJ format string
 * Applies the world matrix to transform vertices to world coordinates
 */
function geometryToOBJ(geometry, worldMatrix) {
    let objContent = '# OBJ file exported from Three.js\n';

    // Clone geometry and apply transformations
    const geo = geometry.clone();
    geo.applyMatrix4(worldMatrix);

    const position = geo.getAttribute('position');
    const normal = geo.getAttribute('normal');
    const index = geo.getIndex();

    // Export vertices
    for (let i = 0; i < position.count; i++) {
        const x = position.getX(i);
        const y = position.getY(i);
        const z = position.getZ(i);
        objContent += `v ${x.toFixed(6)} ${y.toFixed(6)} ${z.toFixed(6)}\n`;
    }

    // Export normals if available
    if (normal) {
        // Transform normals by the normal matrix (inverse transpose of upper 3x3)
        const normalMatrix = new THREE.Matrix3().getNormalMatrix(worldMatrix);
        for (let i = 0; i < normal.count; i++) {
            const nx = normal.getX(i);
            const ny = normal.getY(i);
            const nz = normal.getZ(i);
            const normalVec = new THREE.Vector3(nx, ny, nz).applyMatrix3(normalMatrix).normalize();
            objContent += `vn ${normalVec.x.toFixed(6)} ${normalVec.y.toFixed(6)} ${normalVec.z.toFixed(6)}\n`;
        }
    }

    // Export faces
    if (index) {
        for (let i = 0; i < index.count; i += 3) {
            const a = index.getX(i) + 1;
            const b = index.getX(i + 1) + 1;
            const c = index.getX(i + 2) + 1;
            if (normal) {
                objContent += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
            } else {
                objContent += `f ${a} ${b} ${c}\n`;
            }
        }
    } else {
        for (let i = 0; i < position.count; i += 3) {
            const a = i + 1;
            const b = i + 2;
            const c = i + 3;
            if (normal) {
                objContent += `f ${a}//${a} ${b}//${b} ${c}//${c}\n`;
            } else {
                objContent += `f ${a} ${b} ${c}\n`;
            }
        }
    }

    return objContent;
}

/**
 * Merges multiple geometries into a single OBJ file
