        for (let i = 0; i < position.count; i++) {
            const x = position.getX(i);
            const y = position.getY(i);
            const z = position.getZ(i);
            objContent += `v ${x.toFixed(6)} ${y.toFixed(6)} ${z.toFixed(6)}\n`;
        }

        // Export normals if available
        if (normal) {
            const normalMatrix = new THREE.Matrix3().getNormalMatrix(worldMatrix);
            for (let i = 0; i < normal.count; i++) {
                const nx = normal.getX(i);
                const ny = normal.getY(i);
                const nz = normal.getZ(i);
                const normalVec = new THREE.Vector3(nx, ny, nz).applyMatrix3(normalMatrix).normalize();
                objContent += `vn ${normalVec.x.toFixed(6)} ${normalVec.y.toFixed(6)} ${normalVec.z.toFixed(6)}\n`;
            }
        }

        // Export faces with offset
        if (index) {
            for (let i = 0; i < index.count; i += 3) {
                const a = index.getX(i) + 1 + vertexOffset;
                const b = index.getX(i + 1) + 1 + vertexOffset;
                const c = index.getX(i + 2) + 1 + vertexOffset;
                if (normal) {
                    const na = index.getX(i) + 1 + normalOffset;
                    const nb = index.getX(i + 1) + 1 + normalOffset;
                    const nc = index.getX(i + 2) + 1 + normalOffset;
                    objContent += `f ${a}//${na} ${b}//${nb} ${c}//${nc}\n`;
                } else {
                    objContent += `f ${a} ${b} ${c}\n`;
                }
            }
        } else {
            for (let i = 0; i < position.count; i += 3) {
                const a = i + 1 + vertexOffset;
                const b = i + 2 + vertexOffset;
                const c = i + 3 + vertexOffset;
                if (normal) {
                    const na = i + 1 + normalOffset;
                    const nb = i + 2 + normalOffset;
                    const nc = i + 3 + normalOffset;
                    objContent += `f ${a}//${na} ${b}//${nb} ${c}//${nc}\n`;
                } else {
                    objContent += `f ${a} ${b} ${c}\n`;
                }
            }
        }

        vertexOffset += position.count;
        if (normal) {
            normalOffset += normal.count;
        }
    }

    return objContent;
}

/**
 * Collects all meshes from a group, optionally recursively
 */
function collectMeshes(object, meshList = [], parentMatrix = new THREE.Matrix4()) {
    const worldMatrix = parentMatrix.clone().multiply(object.matrix);

    if (object.isMesh) {
        meshList.push({ mesh: object, worldMatrix: worldMatrix.clone() });
    }

    for (const child of object.children) {
        collectMeshes(child, meshList, worldMatrix);
    }

    return meshList;
}

// Main execution
const scene = createScene();
scene.updateMatrixWorld(true);

const partMeshesDir = '/root/output/part_meshes';
const linksDir = '/root/output/links';

// Find all top-level parts (Groups directly under root)
const parts = [];
for (const child of scene.children) {
    if (child.isGroup) {
        parts.push(child);
    }
}

console.log(`Found ${parts.length} main parts:`);
parts.forEach(p => console.log(`  - ${p.name}`));

// Process each part
for (const part of parts) {
    const partName = part.name;
    const partDir = path.join(partMeshesDir, partName);

    // Create directory for this part
    fs.mkdirSync(partDir, { recursive: true });

    // Collect all meshes that are direct children (not in sub-groups)
    // and also process sub-groups (like cabins)
    const directMeshes = [];
    const subGroups = [];

    for (const child of part.children) {
        if (child.isMesh) {
            directMeshes.push(child);
        } else if (child.isGroup) {
            subGroups.push(child);
        }
    }

    console.log(`\nProcessing part: ${partName}`);
    console.log(`  Direct meshes: ${directMeshes.length}`);
    console.log(`  Sub-groups: ${subGroups.length}`);

    // Export direct meshes
    for (const mesh of directMeshes) {
        mesh.updateMatrixWorld(true);
        const objContent = geometryToOBJ(mesh.geometry, mesh.matrixWorld);
        const fileName = `${mesh.name}.obj`;
        const filePath = path.join(partDir, fileName);
        fs.writeFileSync(filePath, objContent);
        console.log(`  Exported: ${fileName}`);
    }

    // Export sub-groups (each sub-group becomes a folder with its meshes)
    for (const subGroup of subGroups) {
        const subGroupDir = path.join(partDir, subGroup.name);
        fs.mkdirSync(subGroupDir, { recursive: true });

        // Get all meshes in this sub-group
        const subMeshes = collectMeshes(subGroup, [], subGroup.parent.matrixWorld);

        for (const { mesh, worldMatrix } of subMeshes) {
            const objContent = geometryToOBJ(mesh.geometry, worldMatrix);
            const fileName = `${mesh.name}.obj`;
            const filePath = path.join(subGroupDir, fileName);
            fs.writeFileSync(filePath, objContent);
        }
        console.log(`  Exported sub-group: ${subGroup.name} (${subMeshes.length} meshes)`);
    }

    // Create combined link file for this part
    const allMeshes = collectMeshes(part, [], part.parent.matrixWorld);
    const linkObjContent = mergeGeometriesToOBJ(allMeshes);
    const linkFilePath = path.join(linksDir, `${partName}.obj`);
    fs.writeFileSync(linkFilePath, linkObjContent);
    console.log(`  Created link file: ${partName}.obj (${allMeshes.length} meshes merged)`);
}

console.log('\nExport complete!');
